export default function Skills() {
  const [ref, inView] = useInView()

  return (
    <section id="skills" className="section-padding bg-surface-900/40">
      <div className="container-max" ref={ref}>
        {/* Header */}
        <motion.div
          initial={{ y: 20, opacity: 0 }}
          animate={inView ? { y: 0, opacity: 1 } : {}}
          transition={{ duration: 0.6 }}
          className="text-center mb-16"
        >
          <span className="section-label mx-auto">
            <Layers size={10} />
            Навыки
          </span>
          <h2 className="section-title">
            Мой стек <span className="text-gradient">технологий</span>
          </h2>
          <p className="section-subtitle mx-auto text-center">
           Технологии, которые я использую для создания быстрых, красивых и готовых к продакшену веб-решений.
          </p>
        </motion.div>

        {/* Skill cards grid */}
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
          {skills.map((skill, i) => (
            <motion.div
              key={skill.name}
              initial={{ y: 30, opacity: 0 }}
              animate={inView ? { y: 0, opacity: 1 } : {}}
              transition={{ delay: 0.05 * i, duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
            >
              <SkillCard skill={skill} />
            </motion.div>
          ))}
        </div>

        {/* Other skills row */}
        <motion.div
          initial={{ y: 20, opacity: 0 }}
          animate={inView ? { y: 0, opacity: 1 } : {}}
          transition={{ delay: 0.5, duration: 0.5 }}
          className="mt-8 glass rounded-2xl p-6"
        >
          <p className="font-mono text-xs text-slate-500 tracking-wider mb-4">ТАК ЖЕ ЗНАКОМ С</p>
          <div className="flex flex-wrap gap-2">
            {['TypeScript', 'Next.js', 'Vite', 'Framer Motion', 'REST APIs', 'Figma', 'Webpack', 'ESLint', 'Prettier', 'Vercel', 'Storybook', 'Redux'].map((tool) => (
              <span
                key={tool}
                className="px-3 py-1.5 rounded-full bg-white/4 border border-white/8 font-mono text-xs text-slate-400 hover:border-accent/20 hover:text-accent transition-all duration-200 cursor-default"
              >
                {tool}
              </span>
            ))}
          </div>
        </motion.div>
      </div>
    </section>
  )
}

function SkillCard({ skill }) {
  return (
    <motion.div
      whileHover={{ y: -4, scale: 1.02 }}
      transition={{ duration: 0.25, ease: 'easeOut' }}
      className="glass rounded-2xl p-5 relative overflow-hidden group cursor-default"
      style={{ borderColor: `${skill.color}15` }}
    >
      {/* Shimmer effect */}
      <div className="absolute inset-0 shimmer-line opacity-0 group-hover:opacity-100 transition-opacity duration-500" />

      {/* Glow */}
      <div
        className="absolute -top-4 -right-4 w-16 h-16 rounded-full opacity-0 group-hover:opacity-10 blur-xl transition-opacity duration-500"
        style={{ background: skill.color }}
      />

      {/* Icon */}
      <div
        className="w-12 h-12 rounded-xl flex items-center justify-center mb-4 transition-all duration-300"
        style={{
          background: `${skill.color}15`,
          border: `1px solid ${skill.color}25`,
          color: skill.color,
        }}
      >
        {skill.icon}
      </div>

      {/* Name */}
      <h3 className="font-display font-semibold text-white text-base mb-1.5 group-hover:text-white/90">
        {skill.name}
      </h3>

      {/* Description */}
      <p className="font-body text-slate-500 text-xs leading-relaxed mb-4">
        {skill.description}
      </p>

      {/* Progress bar */}
      <div className="h-px bg-white/5 rounded-full overflow-hidden">
        <motion.div
          className="h-full rounded-full"
          style={{ background: skill.color }}
          initial={{ width: 0 }}
          whileInView={{ width: `${skill.level}%` }}
          viewport={{ once: true }}
          transition={{ duration: 1, ease: 'easeOut', delay: 0.2 }}
        />
      </div>

      <div className="flex justify-between mt-1.5">
        <span className="font-mono text-[10px] text-slate-600">Профессиональность</span>
        <span className="font-mono text-[10px]" style={{ color: skill.color }}>{skill.level}%</span>
      </div>
    </motion.div>
  )
}
